const incoming = $input.first()?.json || {};
const rawId = incoming.buyer_id;
const id = Number(rawId);
if (!Number.isSafeInteger(id) || id < 1 || String(rawId ?? '').trim() === '') {
  throw new Error('Invalid buyer_id: expected a positive integer. No CRM request sent.');
}
return [{json:{buyer_id:String(id)}}];

const body = $input.first().json || {};
const buyer = body && body.data && !Array.isArray(body.data) ? body.data : body;
if (buyer.id === undefined || buyer.id === null) {
  throw new Error('KeyCRM buyer payload has no id. Check API response mapping; do not send raw data to the agent.');
}
const hasValue = v => v !== undefined && v !== null && (Array.isArray(v) ? v.length > 0 : String(v).trim() !== '');
return [{
  json: {
    source: 'KeyCRM',
    entity_type: 'buyer',
    buyer_id: buyer.id,
    manager_id: buyer.manager_id ?? null,
    company_id: buyer.company_id ?? null,
    created_at: buyer.created_at ?? null,
    updated_at: buyer.updated_at ?? null,
    has_full_name: hasValue(buyer.full_name),
    has_phone: hasValue(buyer.phone) || hasValue(buyer.phones),
    has_email: hasValue(buyer.email) || hasValue(buyer.emails),
    available_top_level_field_names: Object.keys(buyer).filter(k => !['raw_data','contacts','phones','emails','addresses','shipping','custom_fields','full_name','phone','email'].includes(k)).slice(0,30),
    personal_contact_details_excluded: true,
    include_requested: false,
    note: 'Read-only single buyer. Contacts, notes and shipping data deliberately omitted from AI output. No linked orders or card history queried.'
  }
}];
